def grandfather_existing_staff_applications(apps, schema_editor):
    """Mark existing coordinator/franchise accounts as 'approved' so the new
    RequireApplicationApprovalMiddleware gate doesn't lock out staff who were
    already onboarded before this approval step existed. New registrations
    start "pending" and go through the apply → super-admin review flow.
    """
    User = apps.get_model("accounts", "User")
    User.objects.filter(
        role__code__in=["coordinator", "franchise", "COORDINATOR", "FRANCHISE"]
    ).exclude(application_status="approved").update(application_status="approved")


